/* Tech Robot · unitat 5 «Ordres noves» (funcions: posar nom a un grup de blocs, cridar-lo, funcions dins de bucles, reutilitzar) */
Object.assign(TBADGE, {
  u5nom: { id: 'u5nom', ico: '🏷️', n: "Inventor/a d'ordres|Inventor/a de órdenes", d: 'Has creat la teva primera funció: una ordre nova amb nom.|Has creado tu primera función: una orden nueva con nombre.' },
  u5curt: { id: 'u5curt', ico: '✂️', n: 'Pocs blocs, molta feina|Pocos bloques, mucho trabajo', d: 'Has fet programes curts reutilitzant funcions.|Has hecho programas cortos reutilizando funciones.' },
  u5ciutat: { id: 'u5ciutat', ico: '🏙️', n: 'Ciutat dels robots|Ciudad de los robots', d: 'Projecte acabat: els encàrrecs de la ciutat amb funcions.|Proyecto terminado: los encargos de la ciudad con funciones.' }
});
ROBOT_UNITS[5] = { t: 'Ordres noves|Órdenes nuevas', d: 'Funcions|Funciones', color: '#8B5CF6', s: [
  /* ---------- Sessió 1 · Posa nom a un grup de blocs ---------- */
  { id: 'r5-1', t: 'Posa nom a un grup de blocs|Ponle nombre a un grupo de bloques', min: 35, badge: 'u5nom',
    learn: ['Una funció és un grup de blocs amb un nom: una ordre nova.|Una función es un grupo de bloques con un nombre: una orden nueva.',
      'Per fer servir una funció, la crides amb el seu bloc: en Bit la fa i torna on era.|Para usar una función, la llamas con su bloque: Bit la hace y vuelve donde estaba.',
      'Una funció escrita una vegada es pot cridar moltes vegades.|Una función escrita una vez se puede llamar muchas veces.'],
    steps: [
      { k: 'quiz', ph: 'recorda', w: { map: ['.R.', '.^.', '...'] }, q: 'Recordes el «Si… si no…»? En Bit té una roca davant i el programa diu: <b>Si hi ha un obstacle davant: Gira a la dreta. Si no: Endavant.</b> Què fa?|¿Recuerdas el «Si… si no…»? Bit tiene una roca delante y el programa dice: <b>Si hay un obstáculo delante: Gira a la derecha. Si no: Adelante.</b> ¿Qué hace?',
        opts: ['Gira a la dreta|Gira a la derecha', 'Avança i xoca amb la roca|Avanza y choca con la roca', 'Fa les dues coses|Hace las dos cosas'], a: 0, ex: 'Hi ha un obstacle, així que fa la part del «si» i se salta la del «si no».|Hay un obstáculo, así que hace la parte del «si» y se salta la del «si no».' },
      { k: 'quiz', ph: 'recorda', q: 'I el bucle? Amb <b>Repeteix 3 vegades: Endavant, Endavant</b>, quantes caselles avança en Bit?|¿Y el bucle? Con <b>Repite 3 veces: Adelante, Adelante</b>, ¿cuántas casillas avanza Bit?',
        opts: ['6', '3', '2'], a: 0, ex: '3 vegades × 2 passos = 6 caselles.|3 veces × 2 pasos = 6 casillas.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: "La llibreta d'ordres noves|La libreta de órdenes nuevas", t: "Al poble de l'illa cada dia hi ha més feina, i a en Bit li arriben encàrrecs llarguíssims. En Numi ha tingut una idea: <b>ensenyar-li ordres noves</b>. Quan a casa et diuen «para taula», no t'expliquen plat per plat: ja saps què vol dir!|En el pueblo de la isla cada día hay más trabajo, y a Bit le llegan encargos larguísimos. Numi ha tenido una idea: <b>enseñarle órdenes nuevas</b>. Cuando en casa te dicen «pon la mesa», no te lo explican plato por plato: ¡ya sabes qué quiere decir!" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', t: "BIP! M'ensenyes un grup d'ordres, li posem un <b>nom</b> i l'apunto a la meva llibreta. Després, cada vegada que em diguis aquell nom, faré tots els passos de cop. Serà un bloc nou de color <b>lila</b>!|¡BIP! Me enseñas un grupo de órdenes, le ponemos un <b>nombre</b> y lo apunto en mi libreta. Después, cada vez que me digas ese nombre, haré todos los pasos de golpe. ¡Será un bloque nuevo de color <b>lila</b>!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Funció|Función', t: "Una ordre feta d'altres ordres|Una orden hecha de otras órdenes", anim: 'u5recipe',
          x: "Una <span class='hl'>funció</span> és una ordre nova feta d'altres ordres. «Para taula» vol dir: posa les estovalles, els plats, els gots i els coberts. «Fes el llit» també ho és: estira el llençol, estira la manta i posa el coixí.|Una <span class='hl'>función</span> es una orden nueva hecha de otras órdenes. «Pon la mesa» quiere decir: pon el mantel, los platos, los vasos y los cubiertos. «Haz la cama» también lo es: estira la sábana, estira la manta y pon la almohada.",
          tip: "Fem servir funcions tot el dia sense adonar-nos-en: «renta't les mans» són un munt de passos!|Usamos funciones todo el día sin darnos cuenta: ¡«lávate las manos» son un montón de pasos!" },
        { k: 'Posar nom|Poner nombre', t: 'Un grup de blocs amb nom|Un grupo de bloques con nombre', anim: 'u5pack',
          x: "Per fer una funció, agafes uns quants blocs i els poses un <b>nom</b>. Aquí, <b>Endavant, Gira a l'esquerra, Endavant, Gira a la dreta</b> es diuen <b>escala</b>. A partir d'ara, un sol bloc lila fa la feina dels quatre.|Para hacer una función, coges unos cuantos bloques y les pones un <b>nombre</b>. Aquí, <b>Adelante, Gira a la izquierda, Adelante, Gira a la derecha</b> se llaman <b>escalera</b>. A partir de ahora, un solo bloque lila hace el trabajo de los cuatro." },
        { k: 'Cridar|Llamar', t: 'Cridar una funció|Llamar a una función', anim: 'u5call',
          x: "Posar el bloc de la funció al programa es diu <span class='hl'>cridar</span> la funció. Quan en Bit el troba, <b>va a la funció, en fa tots els blocs i torna</b> al programa per continuar pel bloc següent.|Poner el bloque de la función en el programa se llama <span class='hl'>llamar</span> a la función. Cuando Bit lo encuentra, <b>va a la función, hace todos sus bloques y vuelve</b> al programa para seguir por el bloque siguiente.",
          bad: "La funció es fa sola, només perquè l'has escrit.|La función se hace sola, solo porque la has escrito.", good: 'La funció només es fa quan la crides amb el seu bloc.|La función solo se hace cuando la llamas con su bloque.' },
        { k: 'En Bit ho prova|Bit lo prueba', t: 'Dues escales amb dos blocs|Dos escaleras con dos bloques', demo: { w: { map: ['..#F', '.##.', '>#..'] }, prog: 'A A f', fns: { A: 'f l f r' } },
          x: "Aquí la funció <b>A</b> és l'escala. El programa diu: <b>Funció A, Funció A, Endavant</b>. Cada vegada que en Bit crida la funció, en fa els quatre blocs i puja un esglaó.|Aquí la función <b>A</b> es la escalera. El programa dice: <b>Función A, Función A, Adelante</b>. Cada vez que Bit llama a la función, hace sus cuatro bloques y sube un escalón." }
      ] },
      { k: 'seq', ph: 'mans', q: '«Fes el llit» és una funció de la vida real. <b>Ordena els passos</b> que té a dins.|«Haz la cama» es una función de la vida real. <b>Ordena los pasos</b> que tiene dentro.',
        items: ['Treu el coixí|Quita la almohada', 'Estira el llençol|Estira la sábana', 'Estira la manta|Estira la manta', 'Torna a posar el coixí|Vuelve a poner la almohada'],
        ex: "Ara, quan algú digui «fes el llit», ja saps tots aquests passos. Això és una <b>funció</b>: molts passos amb un sol nom.|Ahora, cuando alguien diga «haz la cama», ya sabes todos estos pasos. Eso es una <b>función</b>: muchos pasos con un solo nombre." },
      { k: 'unplug', ph: 'mans', ico: '💃', title: 'El ball amb nom|El baile con nombre', t: 'Amb algú de casa, inventeu una ordre nova.|Con alguien de casa, inventad una orden nueva.',
        steps: ['Inventeu 3 moviments: per exemple, picar de mans, girar i saltar.|Inventad 3 movimientos: por ejemplo, dar una palmada, girar y saltar.',
          'Poseu-li un nom divertit, com «el ball del robot».|Ponedle un nombre divertido, como «el baile del robot».',
          "Ara una persona diu el nom i l'altra fa els 3 moviments. Ja no cal explicar-los!|Ahora una persona dice el nombre y la otra hace los 3 movimientos. ¡Ya no hace falta explicarlos!",
          'Feu un programa amb la vostra ordre: «ball del robot, un pas endavant, ball del robot».|Haced un programa con vuestra orden: «baile del robot, un paso adelante, baile del robot».'],
        tip: "Acabeu de crear una <b>funció</b>: un grup d'ordres amb nom que podeu fer servir tantes vegades com vulgueu.|Acabáis de crear una <b>función</b>: un grupo de órdenes con nombre que podéis usar tantas veces como queráis." },
      { k: 'quiz', ph: 'prova', w: { map: ['...', '.^.', '...'] }, q: 'La funció <b>mitja volta</b> és: Gira a la dreta, Gira a la dreta. En Bit mira amunt i el programa diu <b>Funció mitja volta</b>. Cap on mira ara?|La función <b>media vuelta</b> es: Gira a la derecha, Gira a la derecha. Bit mira arriba y el programa dice <b>Función media vuelta</b>. ¿Hacia dónde mira ahora?',
        opts: ['↓ Avall|↓ Abajo', '↑ Amunt|↑ Arriba', '→ Dreta|→ Derecha'], a: 0, ex: 'Cridar la funció és fer els seus dos girs: mitja volta.|Llamar a la función es hacer sus dos giros: media vuelta.' },
      { k: 'predict', ph: 'prova', q: 'La funció <b>cantonada</b> és: Endavant, Endavant, Gira a la dreta. El programa la crida <b>dues vegades</b>. On acabarà en Bit?|La función <b>esquina</b> es: Adelante, Adelante, Gira a la derecha. El programa la llama <b>dos veces</b>. ¿Dónde terminará Bit?',
        w: { map: ['.C...', '.#...', '.B#A.', '.#...', '.^...'] }, prog: TP('A A'), fns: { A: TQ('f f r') }, fnName: { A: 'cantonada|esquina' }, a: 'A',
        ex: 'Cada crida fa dos passos i un gir: primer puja dues caselles i gira; després avança dues caselles cap a la dreta.|Cada llamada hace dos pasos y un giro: primero sube dos casillas y gira; después avanza dos casillas hacia la derecha.' },
      { k: 'build', ph: 'prova', q: "En Bit ja té la funció <b>escala</b> apuntada a la llibreta (aquesta no la pots canviar). Fes-la servir per pujar fins a la bandera. Només tens <b>4 blocs</b>!|Bit ya tiene la función <b>escalera</b> apuntada en la libreta (esta no la puedes cambiar). Úsala para subir hasta la bandera. ¡Solo tienes <b>4 bloques</b>!",
        w: { map: ['...#F', '..##.', '.##..', '>#...'] }, pal: ['fwd', 'left', 'right', 'call'], fns: { A: TQ('f l f r') }, fnName: { A: 'escala|escalera' }, max: 4, sol: TQ('A A A f'),
        hint: 'Cada bloc «Funció escala» puja un esglaó. Quants esglaons hi ha? I què falta al final?|Cada bloque «Función escalera» sube un escalón. ¿Cuántos escalones hay? ¿Y qué falta al final?',
        after: 'Amb 4 blocs has fet la feina de 13!|¡Con 4 bloques has hecho el trabajo de 13!' },
      { k: 'spot', ph: 'investiga', q: "En Bit puja bé les escales, però al final xoca. <b>La funció està bé</b>: l'error és al programa. Toca el bloc equivocat.|Bit sube bien las escaleras, pero al final choca. <b>La función está bien</b>: el error está en el programa. Toca el bloque equivocado.",
        w: { map: ['..#F', '.##.', '>#..'] }, prog: TPX('A A l! f'), fns: { A: TQ('f l f r') }, fnName: { A: 'escala|escalera' },
        ex: "Després de les dues escales, en Bit ja mira cap a la bandera. El gir a l'esquerra el fa mirar amunt, fora del camí.|Después de las dos escaleras, Bit ya mira hacia la bandera. El giro a la izquierda le hace mirar arriba, fuera del camino." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Una funció amb el cos! La funció <b>salutació</b> és: aixeca els braços, fes una volta sencera i una reverència. Preparats? <b>Salutació! Salutació! Salutació!</b>|¡Una función con el cuerpo! La función <b>saludo</b> es: levanta los brazos, da una vuelta entera y haz una reverencia. ¿Preparados? <b>¡Saludo! ¡Saludo! ¡Saludo!</b>" },
      { k: 'build', ph: 'repte', q: "Ara la funció l'escrius tu! El programa ja crida <b>baixa l'escala</b> tres vegades, però la funció és buida. Toca dins de la funció i posa-hi els blocs perquè en Bit baixi fins a la bandera.|¡Ahora la función la escribes tú! El programa ya llama a <b>baja la escalera</b> tres veces, pero la función está vacía. Toca dentro de la función y pon los bloques para que Bit baje hasta la bandera.",
        w: { map: ['>#..', '.##.', '..##', '...F'] }, pal: ['fwd', 'left', 'right', 'call'], prog: TQ('A A A'), fnEdit: ['A'], fnName: { A: "baixa l'escala|baja la escalera" }, sol: TQ('A A A'), solFns: { A: TQ('f r f l') },
        hint: 'Pensa només en un esglaó: avança, gira cap avall, baixa una casella i torna a mirar cap a la dreta.|Piensa solo en un escalón: avanza, gira hacia abajo, baja una casilla y vuelve a mirar hacia la derecha.' },
      { k: 'build', ph: 'repte', q: "La torre del rellotge! En Bit mira <b>amunt</b>. Escriu la funció <b>esglaó</b> i crida-la les vegades que calgui. Com a molt <b>8 blocs</b>, comptant els de dins de la funció.|¡La torre del reloj! Bit mira <b>arriba</b>. Escribe la función <b>escalón</b> y llámala las veces que haga falta. Como mucho <b>8 bloques</b>, contando los de dentro de la función.",
        w: { map: ['F#...', '.##..', '..##.', '...##', '....^'] }, pal: ['fwd', 'left', 'right', 'call'], fnEdit: ['A'], fnName: { A: 'esglaó|escalón' }, max: 8, sol: TQ('A A A A'), solFns: { A: TQ('f l f r') },
        hint: "Un esglaó: Endavant, gira cap a l'esquerra, Endavant i torna a mirar amunt. Quants esglaons té la torre?|Un escalón: Adelante, gira hacia la izquierda, Adelante y vuelve a mirar arriba. ¿Cuántos escalones tiene la torre?",
        after: "Fixa't: són els mateixos blocs que l'escala d'abans, però com que en Bit mirava amunt, ara puja cap a l'esquerra.|Fíjate: son los mismos bloques que la escalera de antes, pero como Bit miraba arriba, ahora sube hacia la izquierda." },
      { k: 'create', ph: 'crea', name: 'La meva primera funció|Mi primera función', q: "Ara inventes tu! Escriu la funció <b>la meva ordre</b> i crida-la per recollir les 4 estrelles i arribar a la bandera.|¡Ahora inventas tú! Escribe la función <b>mi orden</b> y llámala para recoger las 4 estrellas y llegar a la bandera.",
        crit: ['Posa blocs dins de la funció|Pon bloques dentro de la función', 'Crida la funció almenys 2 vegades|Llama a la función al menos 2 veces', 'Recull les 4 estrelles i acaba a la bandera|Recoge las 4 estrellas y termina en la bandera'],
        check: p => bitCountK(p, ['call']) >= 2 ? null : 'Funciona! Però crida la teva funció almenys 2 vegades: per això serveixen.|¡Funciona! Pero llama a tu función al menos 2 veces: para eso sirven.',
        w: { map: ['....*F', 'R..*..', '..*..R', '.*....', '>..R..'] }, pal: ['fwd', 'left', 'right', 'call'], fnEdit: ['A'], fnName: { A: 'la meva ordre|mi orden' }, sol: TQ('A A A A f'), solFns: { A: TQ('f l f r') } },
      { k: 'quiz', ph: 'tanca', q: 'Per acabar: què és una <b>funció</b>?|Para terminar: ¿qué es una <b>función</b>?', opts: ['Un grup de blocs amb un nom, que fas servir com una ordre nova|Un grupo de bloques con un nombre, que usas como una orden nueva', 'Un bloc que fa anar en Bit més de pressa|Un bloque que hace ir a Bit más deprisa', 'Un error del programa|Un error del programa'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Quan fa en Bit els blocs d\'una funció?|¿Cuándo hace Bit los bloques de una función?', opts: ['Cada vegada que el programa la crida|Cada vez que el programa la llama', "Només el primer cop que l'escrius|Solo la primera vez que la escribes", 'Mai: les funcions només són per mirar-les|Nunca: las funciones solo son para mirarlas'], a: 0,
        ex: 'Si no la crides, la funció espera a la llibreta sense fer res.|Si no la llamas, la función espera en la libreta sin hacer nada.' },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 2 · Funcions dins de bucles ---------- */
  { id: 'r5-2', t: 'Funcions dins de bucles|Funciones dentro de bucles', min: 35,
    learn: ["Una funció es pot posar dins d'un bucle: Repeteix N vegades la funció.|Una función se puede poner dentro de un bucle: Repite N veces la función.",
      'Un error dins d\'una funció surt cada vegada que la crides.|Un error dentro de una función sale cada vez que la llamas.',
      "Per arreglar-lo, n'hi ha prou de canviar la funció, en un sol lloc.|Para arreglarlo, basta con cambiar la función, en un solo sitio."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'En Bit té la funció <b>salt</b>: Endavant, Endavant. Si el programa diu <b>Funció salt, Funció salt</b>, quantes caselles avança?|Bit tiene la función <b>salto</b>: Adelante, Adelante. Si el programa dice <b>Función salto, Función salto</b>, ¿cuántas casillas avanza?',
        opts: ['4', '2', '1'], a: 0, ex: 'Cada crida fa els dos Endavant de la funció: 2 + 2 = 4.|Cada llamada hace los dos Adelante de la función: 2 + 2 = 4.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: "L'escala del mirador|La escalera del mirador", t: "Dalt del turó de l'illa hi ha un mirador des d'on es veu tot el mar. Per arribar-hi cal pujar una escala llarguíssima… En Bit ja sap la funció <b>escala</b>. I si la posem <b>dins d'un bucle</b>?|En lo alto de la colina de la isla hay un mirador desde donde se ve todo el mar. Para llegar hay que subir una escalera larguísima… Bit ya sabe la función <b>escalera</b>. ¿Y si la ponemos <b>dentro de un bucle</b>?" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', w: { map: ['.....F', '....##', '...##.', '..##..', '.##...', '>#....'] }, t: "BIP… Un bucle repeteix blocs. Una funció és un grup de blocs amb nom. Si poso la funció dins del bucle… <b>faré l'escala sencera tantes vegades com digui el número</b>!|BIP… Un bucle repite bloques. Una función es un grupo de bloques con nombre. Si pongo la función dentro del bucle… ¡<b>haré la escalera entera tantas veces como diga el número</b>!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Funció + bucle|Función + bucle', t: "Una funció dins d'un bucle|Una función dentro de un bucle", anim: 'u5loopfn',
          x: "Dins d'un <b>Repeteix</b> hi pots posar el bloc d'una funció. <b>Repeteix 3 vegades: Funció escala</b> vol dir: fes l'escala, fes l'escala i fes l'escala. Tres esglaons amb només dos blocs al programa!|Dentro de un <b>Repite</b> puedes poner el bloque de una función. <b>Repite 3 veces: Función escalera</b> quiere decir: haz la escalera, haz la escalera y haz la escalera. ¡Tres escalones con solo dos bloques en el programa!" },
        { k: 'En Bit ho prova|Bit lo prueba', t: 'Tres esglaons i tres estrelles|Tres escalones y tres estrellas', demo: { w: { map: ['...*F', '..*#.', '.*#..', '>#...'] }, prog: '3{ A } f', fns: { A: 'f l f r' } },
          x: "La funció <b>A</b> és l'escala. El bucle la repeteix 3 vegades i, a cada esglaó, en Bit recull una estrella. Fixa't com s'il·luminen els blocs de la funció a cada volta del bucle.|La función <b>A</b> es la escalera. El bucle la repite 3 veces y, en cada escalón, Bit recoge una estrella. Fíjate en cómo se iluminan los bloques de la función en cada vuelta del bucle." },
        { k: 'Compte!|¡Cuidado!', t: 'Un error a la funció surt cada vegada|Un error en la función sale cada vez', anim: 'u5bugfn',
          x: "Si la funció té un bloc equivocat, l'error es repeteix <b>cada vegada</b> que la crides. La bona notícia: només l'has d'arreglar <b>en un lloc</b>, dins de la funció, i queda bé a totes les crides.|Si la función tiene un bloque equivocado, el error se repite <b>cada vez</b> que la llamas. La buena noticia: solo tienes que arreglarlo <b>en un sitio</b>, dentro de la función, y queda bien en todas las llamadas.",
          bad: "Canviar el programa quan l'error és a dins de la funció.|Cambiar el programa cuando el error está dentro de la función.", good: "Si l'error es repeteix igual cada vegada, mira dins de la funció.|Si el error se repite igual cada vez, mira dentro de la función." },
        { k: 'Bucle o funció?|¿Bucle o función?', t: 'La mateixa funció, en dos llocs|La misma función, en dos sitios', demo: { w: { map: ['..*..', '.###.', '>#.#F'] }, prog: '2{ A } r 2{ A }', fns: { A: 'f l f r' } },
          x: "El <b>bucle</b> repeteix ara mateix, un cop darrere l'altre. La <b>funció</b> és un grup amb nom que pots cridar on vulguis: dins d'un bucle, fora, o en dos llocs diferents. Aquí la mateixa funció fa pujar en Bit… i, després de girar, el fa baixar!|El <b>bucle</b> repite ahora mismo, una vez tras otra. La <b>función</b> es un grupo con nombre que puedes llamar donde quieras: dentro de un bucle, fuera, o en dos sitios distintos. Aquí la misma función hace subir a Bit… ¡y, después de girar, lo hace bajar!" }
      ] },
      { k: 'seq', ph: 'mans', q: 'Com es fa una escala llarga amb una funció i un bucle? <b>Ordena els passos</b> del programador/a.|¿Cómo se hace una escalera larga con una función y un bucle? <b>Ordena los pasos</b> del programador/a.',
        items: ['Mira el camí i busca el tros que es repeteix|Mira el camino y busca el trozo que se repite', "Posa aquest tros dins d'una funció amb nom|Pon este trozo dentro de una función con nombre", "Posa la funció dins d'un bucle|Pon la función dentro de un bucle", 'Compta quantes vegades cal i posa aquest número al bucle|Cuenta cuántas veces hace falta y pon ese número en el bucle'],
        ex: 'Primer es pensa i després es posen blocs: així treballen els programadors.|Primero se piensa y después se ponen bloques: así trabajan los programadores.' },
      { k: 'unplug', ph: 'mans', ico: '🔁', title: 'El ball que es repeteix|El baile que se repite', t: "Amb algú de casa, feu un ball amb una funció dins d'un bucle.|Con alguien de casa, haced un baile con una función dentro de un bucle.",
        steps: ['Inventeu la funció «pas de ball»: per exemple, un pas al costat, un aplaudiment i un salt.|Inventad la función «paso de baile»: por ejemplo, un paso al lado, una palmada y un salto.',
          'El programa és: «Repeteix 4 vegades: pas de ball». Feu-lo!|El programa es: «Repite 4 veces: paso de baile». ¡Hacedlo!',
          "Ara canvieu el salt per una volta, només dins de la funció. Què passa? El canvi surt les 4 vegades!|Ahora cambiad el salto por una vuelta, solo dentro de la función. ¿Qué pasa? ¡El cambio sale las 4 veces!",
          'Canvieu els papers: ara inventa la funció l\'altra persona.|Cambiad los papeles: ahora inventa la función la otra persona.'],
        tip: "Si canvies una cosa dins de la funció, canvia a totes les vegades que la fas. Per això un error a la funció es veu cada vegada.|Si cambias algo dentro de la función, cambia en todas las veces que la haces. Por eso un error en la función se ve cada vez." },
      { k: 'predict', ph: 'prova', q: 'La funció <b>cantonada</b> és: Endavant, Endavant, Gira a la dreta. El programa diu <b>Repeteix 3 vegades: Funció cantonada</b>. On acabarà en Bit?|La función <b>esquina</b> es: Adelante, Adelante, Gira a la derecha. El programa dice <b>Repite 3 veces: Función esquina</b>. ¿Dónde terminará Bit?',
        w: { map: ['>#C', '#.#', 'A#B'] }, prog: TP('3{ A }'), fns: { A: TQ('f f r') }, fnName: { A: 'cantonada|esquina' }, a: 'A',
        ex: "1a vegada: fins a la cantonada de dalt a la dreta. 2a: fins a baix a la dreta. 3a: fins a baix a l'esquerra.|1.ª vez: hasta la esquina de arriba a la derecha. 2.ª: hasta abajo a la derecha. 3.ª: hasta abajo a la izquierda." },
      { k: 'spot', ph: 'investiga', q: 'En Bit ha de pujar fins a la bandera, però es queda a mig camí. La funció <b>escala</b> està bé. <b>Toca el bloc que cal canviar.</b>|Bit tiene que subir hasta la bandera, pero se queda a medio camino. La función <b>escalera</b> está bien. <b>Toca el bloque que hay que cambiar.</b>',
        w: { map: ['....F', '...##', '..##.', '.##..', '>#...'] }, prog: TPX('3!{ A }'), fns: { A: TQ('f l f r') }, fnName: { A: 'escala|escalera' },
        ex: 'Hi ha 4 esglaons i el bucle només es repeteix 3 vegades. Cal canviar el número del bucle: Repeteix 4 vegades.|Hay 4 escalones y el bucle solo se repite 3 veces. Hay que cambiar el número del bucle: Repite 4 veces.' },
      { k: 'move', ph: 'pausa', secs: 30, t: 'La funció <b>esglaó</b>: aixeca un genoll ben amunt i després l\'altre. Ara, <b>Repeteix 5 vegades: esglaó</b>! Quants genolls has aixecat?|La función <b>escalón</b>: levanta una rodilla bien arriba y después la otra. ¡Ahora, <b>Repite 5 veces: escalón</b>! ¿Cuántas rodillas has levantado?' },
      { k: 'build', ph: 'repte', q: "Puja fins al mirador! La funció <b>escala</b> ja està feta. Fes-la servir dins d'un bucle. Només tens <b>2 blocs</b>!|¡Sube hasta el mirador! La función <b>escalera</b> ya está hecha. Úsala dentro de un bucle. ¡Solo tienes <b>2 bloques</b>!",
        w: { map: ['.....F', '....##', '...##.', '..##..', '.##...', '>#....'] }, pal: ['fwd', 'left', 'right', 'rep', 'call'], fns: { A: TQ('f l f r') }, fnName: { A: 'escala|escalera' }, max: 2, sol: TQ('5{ A }'),
        hint: 'Posa un Repeteix i, a dins, la funció. Compta els esglaons per saber el número del bucle.|Pon un Repite y, dentro, la función. Cuenta los escalones para saber el número del bucle.' },
      { k: 'build', ph: 'repte', q: "Al mercat, en Bit ha de portar 3 caixes a 3 cases. El programa ja té el bucle: <b>escriu la funció reparteix</b>, que agafa una caixa i la porta a la casa del costat.|En el mercado, Bit tiene que llevar 3 cajas a 3 casas. El programa ya tiene el bucle: <b>escribe la función reparte</b>, que coge una caja y la lleva a la casa de al lado.",
        w: { map: ['>bHbHbH', '..R..R.'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'rep', 'call'], prog: TQ('3{ A }'), fnEdit: ['A'], fnName: { A: 'reparteix|reparte' }, sol: TQ('3{ A }'), solFns: { A: TQ('f p f d') },
        hint: 'Pensa en una sola entrega: avança fins a la caixa, agafa-la, avança fins a la casa i deixa-la.|Piensa en una sola entrega: avanza hasta la caja, cógela, avanza hasta la casa y déjala.' },
      { k: 'build', ph: 'repte', q: "Ui! La funció <b>zig-zag</b> té un error i en Bit dona voltes sense parar. L'error <b>surt cada vegada</b> que el bucle crida la funció. Arregla la funció!|¡Uy! La función <b>zigzag</b> tiene un error y Bit da vueltas sin parar. El error <b>sale cada vez</b> que el bucle llama a la función. ¡Arregla la función!",
        w: { map: ['>...R', '.*...', 'R.*..', '...*F'] }, pal: ['fwd', 'left', 'right', 'rep', 'call'], prog: TQ('3{ A } f'), fns: { A: TQ('f r f r') }, fnEdit: ['A'], fnName: { A: 'zig-zag|zigzag' }, sol: TQ('3{ A } f'), solFns: { A: TQ('f r f l') },
        hint: 'Fes «Pas a pas» i mira el segon gir de la funció: cap on ha de mirar en Bit per anar a buscar el següent esglaó?|Haz «Paso a paso» y mira el segundo giro de la función: ¿hacia dónde tiene que mirar Bit para ir a buscar el siguiente escalón?' },
      { k: 'build', ph: 'repte', q: "La muntanya del mirador: puja fins al cim (l'estrella) i baixa fins a la bandera. Tens la funció <b>escala</b> i només <b>5 blocs</b>. Pista secreta: la mateixa funció també serveix per baixar!|La montaña del mirador: sube hasta la cima (la estrella) y baja hasta la bandera. Tienes la función <b>escalera</b> y solo <b>5 bloques</b>. Pista secreta: ¡la misma función también sirve para bajar!",
        w: { map: ['...*...', '..###..', '.##.##.', '>#...#F'] }, pal: ['fwd', 'left', 'right', 'rep', 'call'], fns: { A: TQ('f l f r') }, fnName: { A: 'escala|escalera' }, max: 5, sol: TQ('3{ A } r 3{ A }'),
        hint: "Puja amb un bucle. Al cim, gira cap avall i torna a posar el mateix bucle.|Sube con un bucle. En la cima, gira hacia abajo y vuelve a poner el mismo bucle.",
        after: 'Una sola funció ha servit per pujar i per baixar: en Bit fa els blocs <b>des d\'on és i cap on mira</b>.|Una sola función ha servido para subir y para bajar: Bit hace los bloques <b>desde donde está y hacia donde mira</b>.' },
      { k: 'create', ph: 'crea', name: 'Les onades de la platja|Las olas de la playa', q: "Inventa la teva funció (es diu <b>tros</b>) i posa-la <b>dins d'un bucle</b> per recollir les 3 estrelles i arribar a la bandera. Pots fer escales, onades o el que se t'acudeixi!|Inventa tu función (se llama <b>trozo</b>) y ponla <b>dentro de un bucle</b> para recoger las 3 estrellas y llegar a la bandera. ¡Puedes hacer escaleras, olas o lo que se te ocurra!",
        crit: ['Escriu la funció «tros»|Escribe la función «trozo»', "Posa la funció dins d'un bucle|Pon la función dentro de un bucle", 'Recull les 3 estrelles i arriba a la bandera|Recoge las 3 estrellas y llega a la bandera'],
        check: p => p.some(b => b.k === 'rep' && bitCountK(b.b, ['call'])) ? null : "Funciona! Ara posa la funció <b>dins d'un bucle</b> perquè es repeteixi sola.|¡Funciona! Ahora pon la función <b>dentro de un bucle</b> para que se repita sola.",
        w: { map: ['R..R..R', '.......', '..R...R', '.*.*.*.', '>.....F'] }, pal: ['fwd', 'left', 'right', 'rep', 'call'], fnEdit: ['A'], fnName: { A: 'tros|trozo' }, sol: TQ('3{ A }'), solFns: { A: TQ('f l f r f r f l') } },
      { k: 'quiz', ph: 'tanca', q: 'Una funció té un error i el bucle la crida <b>4 vegades</b>. Quantes vegades surt l\'error?|Una función tiene un error y el bucle la llama <b>4 veces</b>. ¿Cuántas veces sale el error?', opts: ['4 vegades|4 veces', '1 vegada|1 vez', 'Cap|Ninguna'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'I quants llocs has d\'arreglar?|¿Y cuántos sitios tienes que arreglar?', opts: ['Un: dins de la funció|Uno: dentro de la función', 'Quatre: un per cada vegada|Cuatro: uno por cada vez', "Cap: s'arregla sol|Ninguno: se arregla solo"], a: 0,
        ex: 'Arregles la funció una vegada i queda bé a totes les crides.|Arreglas la función una vez y queda bien en todas las llamadas.' },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 3 · Pocs blocs, molta feina ---------- */
  { id: 'r5-3', t: 'Pocs blocs, molta feina|Pocos bloques, mucho trabajo', min: 35, badge: 'u5curt',
    learn: ['Reutilitzar és escriure un tros una vegada i fer-lo servir moltes.|Reutilizar es escribir un trozo una vez y usarlo muchas.',
      'Pots tenir dues funcions i cridar-les en l\'ordre que calgui.|Puedes tener dos funciones y llamarlas en el orden que haga falta.',
      'Amb funcions, els programes són més curts i els errors s\'arreglen en un sol lloc.|Con funciones, los programas son más cortos y los errores se arreglan en un solo sitio.'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Quin programa fa pujar en Bit <b>5 esglaons</b> amb la funció escala?|¿Qué programa hace subir a Bit <b>5 escalones</b> con la función escalera?',
        opts: ['Repeteix 5 vegades: Funció escala|Repite 5 veces: Función escalera', 'Repeteix 2 vegades: Funció escala|Repite 2 veces: Función escalera', 'Funció escala, una sola vegada|Función escalera, una sola vez'], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'Un xip amb poca memòria|Un chip con poca memoria', t: "Al laboratori de l'illa han posat a en Bit un xip nou, molt ràpid… però <b>hi caben pocs blocs</b>. Si el programa és massa llarg, no hi cap! Avui aprendràs a fer programes <b>curts</b> que fan molta feina.|En el laboratorio de la isla le han puesto a Bit un chip nuevo, muy rápido… pero <b>caben pocos bloques</b>. Si el programa es demasiado largo, ¡no cabe! Hoy aprenderás a hacer programas <b>cortos</b> que hacen mucho trabajo." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', t: "BIP! El truc és <b>reutilitzar</b>: escric un tros una vegada, li poso nom i el crido tantes vegades com calgui. Mira el comptador de blocs de dalt del programa: compta els del programa i els de dins de les funcions que escrius.|¡BIP! El truco es <b>reutilizar</b>: escribo un trozo una vez, le pongo nombre y lo llamo tantas veces como haga falta. Mira el contador de bloques de encima del programa: cuenta los del programa y los de dentro de las funciones que escribes." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Reutilitzar|Reutilizar', t: "Escriu-ho una vegada, fes-ho servir moltes|Escríbelo una vez, úsalo muchas", anim: 'u5short',
          x: "<span class='hl'>Reutilitzar</span> és fer servir el mateix tros moltes vegades sense tornar-lo a escriure. Tres escales escrites bloc a bloc són 12 blocs; amb una funció i un bucle, només 6.|<span class='hl'>Reutilizar</span> es usar el mismo trozo muchas veces sin volver a escribirlo. Tres escaleras escritas bloque a bloque son 12 bloques; con una función y un bucle, solo 6.",
          tip: 'Els programadors diuen: «no ho escriguis dues vegades». Si un tros es repeteix, mereix un nom.|Los programadores dicen: «no lo escribas dos veces». Si un trozo se repite, merece un nombre.' },
        { k: 'Dues funcions|Dos funciones', t: 'Funció A i funció B|Función A y función B', anim: 'u5two',
          x: "Pots tenir <b>dues funcions</b> amb noms diferents, per exemple <b>puja</b> i <b>baixa</b>, i cridar-les en l'ordre que vulguis: puja, baixa, puja, puja, baixa… Cada una és una ordre nova.|Puedes tener <b>dos funciones</b> con nombres distintos, por ejemplo <b>sube</b> y <b>baja</b>, y llamarlas en el orden que quieras: sube, baja, sube, sube, baja… Cada una es una orden nueva." },
        { k: 'En Bit ho prova|Bit lo prueba', t: 'Dues funcions en acció|Dos funciones en acción', demo: { w: { map: ['..##.', '.####', '>#..F'] }, prog: 'A A B B', fns: { A: 'f l f r', B: 'f r f l' } },
          x: "La funció <b>A</b> puja un esglaó i la <b>B</b> en baixa un. El programa només té 4 blocs: dues vegades A i dues vegades B. Mira com en Bit salta d'una funció a l'altra.|La función <b>A</b> sube un escalón y la <b>B</b> baja uno. El programa solo tiene 4 bloques: dos veces A y dos veces B. Mira cómo Bit salta de una función a la otra." },
        { k: 'Compte!|¡Cuidado!', t: "Primer que funcioni, després que sigui curt|Primero que funcione, después que sea corto", demo: { w: { map: ['>#*', '#.#', '*#*'] }, prog: 'A A A A', fns: { A: 'f f r' } },
          x: "No cal fer-ho curt a la primera. Primer aconsegueix que funcioni; després busca el tros que es repeteix (aquí, cada costat del jardí) i converteix-lo en una funció.|No hace falta hacerlo corto a la primera. Primero consigue que funcione; después busca el trozo que se repite (aquí, cada lado del jardín) y conviértelo en una función.",
          bad: 'Voler fer el programa curt abans de saber si funciona.|Querer hacer el programa corto antes de saber si funciona.', good: 'Fer que funcioni i, després, escurçar-lo amb funcions.|Hacer que funcione y, después, acortarlo con funciones.' }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Compta! El programa és <b>Repeteix 3 vegades: Funció escala</b>, i la funció escala té <b>Endavant, Gira a l\'esquerra, Endavant, Gira a la dreta</b>. Quants blocs són en total?|¡Cuenta! El programa es <b>Repite 3 veces: Función escalera</b>, y la función escalera tiene <b>Adelante, Gira a la izquierda, Adelante, Gira a la derecha</b>. ¿Cuántos bloques son en total?',
        opts: ['6 blocs|6 bloques', '12 blocs|12 bloques', '2 blocs|2 bloques'], a: 0, ex: '2 blocs al programa (el bucle i la funció) + 4 a dins de la funció = 6. Sense funció ni bucle en serien 12.|2 bloques en el programa (el bucle y la función) + 4 dentro de la función = 6. Sin función ni bucle serían 12.' },
      { k: 'unplug', ph: 'mans', ico: '✂️', title: 'El missatge més curt|El mensaje más corto', t: 'Amb algú de casa, feu un concurs de programes curts.|Con alguien de casa, haced un concurso de programas cortos.',
        steps: ["Escriviu en un paper com anar de la porta de casa fins a la cuina, ordre a ordre.|Escribid en un papel cómo ir de la puerta de casa hasta la cocina, orden a orden.",
          'Compteu quantes ordres heu escrit.|Contad cuántas órdenes habéis escrito.',
          'Busqueu trossos que es repeteixin i poseu-los un nom. Per exemple, «passadís» = tres passos i un gir.|Buscad trozos que se repitan y ponedles un nombre. Por ejemplo, «pasillo» = tres pasos y un giro.',
          "Torneu a escriure el camí fent servir els noms nous. Quantes ordres us heu estalviat?|Volved a escribir el camino usando los nombres nuevos. ¿Cuántas órdenes os habéis ahorrado?"] },
      { k: 'predict', ph: 'prova', q: 'Funció <b>recte</b>: Endavant, Endavant. Funció <b>volta</b>: Gira a l\'esquerra, Endavant, Gira a l\'esquerra. El programa és <b>recte, volta, recte</b>. On acabarà en Bit?|Función <b>recto</b>: Adelante, Adelante. Función <b>vuelta</b>: Gira a la izquierda, Adelante, Gira a la izquierda. El programa es <b>recto, vuelta, recto</b>. ¿Dónde terminará Bit?',
        w: { map: ['A#B..', '>###C'] }, prog: TP('A B A'), fns: { A: TQ('f f'), B: TQ('l f l') }, fnName: { A: 'recte|recto', B: 'volta|vuelta' }, a: 'A',
        ex: "Recte el porta 2 caselles a la dreta; volta el fa pujar i mirar a l'esquerra; i recte el torna 2 caselles cap a l'esquerra.|Recto lo lleva 2 casillas a la derecha; vuelta lo hace subir y mirar a la izquierda; y recto lo devuelve 2 casillas hacia la izquierda." },
      { k: 'spot', ph: 'investiga', q: 'Aquest programa funciona, però es pot fer més curt: hi ha un tros escrit a mà que és <b>igual que la funció baixa</b>. Toca el primer bloc d\'aquest tros.|Este programa funciona, pero se puede hacer más corto: hay un trozo escrito a mano que es <b>igual que la función baja</b>. Toca el primer bloque de ese trozo.',
        w: { map: ['>#..', '.##.', '..#F'] }, prog: TPX('A f! r f l f'), fns: { A: TQ('f r f l') }, fnName: { A: 'baixa|baja' },
        ex: "Endavant, Gira a la dreta, Endavant, Gira a l'esquerra és la funció baixa. Si la crides en lloc d'escriure-la, t'estalvies 3 blocs.|Adelante, Gira a la derecha, Adelante, Gira a la izquierda es la función baja. Si la llamas en lugar de escribirla, te ahorras 3 bloques." },
      { k: 'quiz', ph: 'investiga', q: 'Dos programes porten en Bit al mateix lloc. El primer té 16 blocs i cap funció. El segon té 8 blocs i fa servir una funció. Si hi ha un error a l\'escala, quin és més fàcil d\'arreglar?|Dos programas llevan a Bit al mismo sitio. El primero tiene 16 bloques y ninguna función. El segundo tiene 8 bloques y usa una función. Si hay un error en la escalera, ¿cuál es más fácil de arreglar?',
        opts: ["El de la funció: l'error s'arregla en un sol lloc|El de la función: el error se arregla en un solo sitio", 'El llarg: té més blocs per triar|El largo: tiene más bloques donde elegir', 'Tots dos igual|Los dos igual'], a: 0,
        ex: "Al llarg, l'error pot estar copiat a molts llocs. Al curt, és a la funció i l'arregles una sola vegada.|En el largo, el error puede estar copiado en muchos sitios. En el corto, está en la función y lo arreglas una sola vez." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Programa llarg: aplaudeix, aplaudeix, salta, aplaudeix, aplaudeix, salta, aplaudeix, aplaudeix, salta. Uf! Programa curt: <b>Repeteix 3 vegades: «aplaudeix, aplaudeix, salta»</b>. Fes-lo!|Programa largo: aplaude, aplaude, salta, aplaude, aplaude, salta, aplaude, aplaude, salta. ¡Uf! Programa corto: <b>Repite 3 veces: «aplaude, aplaude, salta»</b>. ¡Hazlo!" },
      { k: 'build', ph: 'repte', q: 'La volta al jardí: recull les 3 estrelles de les cantonades. Aquí <b>no hi ha bucle</b> i només tens <b>8 blocs</b>. Fes una funció!|La vuelta al jardín: recoge las 3 estrellas de las esquinas. Aquí <b>no hay bucle</b> y solo tienes <b>8 bloques</b>. ¡Haz una función!',
        w: { map: ['>###*', '#...#', '#...#', '#...#', '*###*'] }, pal: ['fwd', 'left', 'right', 'call'], fnEdit: ['A'], fnName: { A: 'costat|lado' }, max: 8, sol: TQ('A A A'), solFns: { A: TQ('f f f f r') },
        hint: 'Cada costat del jardí és igual: 4 passos endavant i un gir. Aquesta és la teva funció.|Cada lado del jardín es igual: 4 pasos adelante y un giro. Esta es tu función.' },
      { k: 'build', ph: 'repte', q: "La serra de les estrelles: en Bit puja i baixa en un ordre que canvia. Fes dues funcions, <b>puja</b> i <b>baixa</b>, i crida-les en l'ordre bo. Màxim <b>14 blocs</b>.|La sierra de las estrellas: Bit sube y baja en un orden que cambia. Haz dos funciones, <b>sube</b> y <b>baja</b>, y llámalas en el orden correcto. Máximo <b>14 bloques</b>.",
        w: { map: ['R...*.R', '.*.*.*F', '>.*.R..'] }, pal: ['fwd', 'left', 'right', 'call'], fnEdit: ['A', 'B'], fnName: { A: 'puja|sube', B: 'baixa|baja' }, max: 14, sol: TQ('A B A A B f'), solFns: { A: TQ('f l f r'), B: TQ('f r f l') },
        hint: 'Segueix les estrelles amb el dit i digues en veu alta: puja, baixa, puja… Cada funció és un sol esglaó.|Sigue las estrellas con el dedo y di en voz alta: sube, baja, sube… Cada función es un solo escalón.' },
      { k: 'build', ph: 'repte', q: 'Repartiment al carrer de dalt i al de baix: 5 caixes i 5 cases. Fes la funció <b>reparteix</b> i fes-la servir als dos carrers. Màxim <b>12 blocs</b>!|Reparto en la calle de arriba y en la de abajo: 5 cajas y 5 casas. Haz la función <b>reparte</b> y úsala en las dos calles. ¡Máximo <b>12 bloques</b>!',
        w: { map: ['>bHbHbH', '......#', '..HbHb#'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'rep', 'call'], fnEdit: ['A'], fnName: { A: 'reparteix|reparte' }, max: 12, sol: TQ('3{ A } r f f r 2{ A }'), solFns: { A: TQ('f p f d') },
        hint: 'Al carrer de dalt, la funció es repeteix 3 vegades. Després baixa pel camí i gira. Al carrer de baix, 2 vegades més.|En la calle de arriba, la función se repite 3 veces. Después baja por el camino y gira. En la calle de abajo, 2 veces más.' },
      { k: 'create', ph: 'crea', name: 'El rècord de blocs|El récord de bloques', q: 'El repte dels pocs blocs! Recull les 5 estrelles i arriba a la bandera amb <b>10 blocs com a màxim</b>. Fes servir la funció <b>el meu truc</b> (i un bucle, si vols).|¡El reto de los pocos bloques! Recoge las 5 estrellas y llega a la bandera con <b>10 bloques como máximo</b>. Usa la función <b>mi truco</b> (y un bucle, si quieres).',
        crit: ['Recull les 5 estrelles i arriba a la bandera|Recoge las 5 estrellas y llega a la bandera', 'Fes servir almenys una funció|Usa al menos una función', '10 blocs com a màxim|10 bloques como máximo'],
        check: p => bitCountK(p, ['call']) ? null : 'Funciona! Ara fes-ho cridant la funció <b>el meu truc</b>.|¡Funciona! Ahora hazlo llamando a la función <b>mi truco</b>.',
        w: { map: ['R.....R', '...*...', '..*.*..', '.*...*.', '>....FR'] }, pal: ['fwd', 'left', 'right', 'rep', 'call'], fnEdit: ['A'], fnName: { A: 'el meu truc|mi truco' }, max: 10, sol: TQ('3{ A } r 2{ A } f'), solFns: { A: TQ('f l f r') } },
      { k: 'quiz', ph: 'tanca', q: 'Què vol dir <b>reutilitzar</b> un tros de programa?|¿Qué quiere decir <b>reutilizar</b> un trozo de programa?', opts: ["Escriure'l una vegada i fer-lo servir moltes vegades|Escribirlo una vez y usarlo muchas veces", "Esborrar-lo i tornar-lo a escriure|Borrarlo y volver a escribirlo", 'Fer-lo més llarg|Hacerlo más largo'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Quins blocs compta el comptador de blocs?|¿Qué bloques cuenta el contador de bloques?', opts: ['Els del programa i els de dins de les funcions que escric|Los del programa y los de dentro de las funciones que escribo', 'Només els del programa|Solo los del programa', 'Només els de les funcions|Solo los de las funciones'], a: 0,
        ex: 'Per això una funció estalvia blocs quan la crides més d\'una vegada.|Por eso una función ahorra bloques cuando la llamas más de una vez.' },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 4 · Projecte: la ciutat dels robots ---------- */
  { id: 'r5-4', t: 'Projecte: la ciutat dels robots|Proyecto: la ciudad de los robots', min: 40, proj: true, badge: 'u5ciutat',
    learn: ['Planificar és mirar què es repeteix i posar-hi nom abans de programar.|Planificar es mirar qué se repite y ponerle nombre antes de programar.',
      'Un bon nom de funció explica què fa: porta-la, puja, costat…|Un buen nombre de función explica qué hace: llévala, sube, lado…',
      "Una funció fa els seus blocs des d'on és en Bit: serveix per a molts carrers.|Una función hace sus bloques desde donde está Bit: sirve para muchas calles."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Una funció escrita una vegada…|Una función escrita una vez…', opts: ['…es pot cridar tantes vegades com vulguis|…se puede llamar tantas veces como quieras', '…només es pot fer servir una vegada|…solo se puede usar una vez', "…s'esborra quan s'acaba|…se borra cuando se acaba"], a: 0,
        ex: 'Per això les funcions fan els programes més curts.|Por eso las funciones hacen los programas más cortos.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'La ciutat dels robots|La ciudad de los robots', t: "El poble de l'illa ha crescut tant que ara li diuen <b>la ciutat dels robots</b>! Avui és el gran dia dels encàrrecs: les cases esperen caixes i en Bit és el repartidor. Però aquesta vegada té un superpoder: <b>les ordres noves</b>.|¡El pueblo de la isla ha crecido tanto que ahora lo llaman <b>la ciudad de los robots</b>! Hoy es el gran día de los encargos: las casas esperan cajas y Bit es el repartidor. Pero esta vez tiene un superpoder: <b>las órdenes nuevas</b>." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', w: { map: ['>#.###.', '.b.H.b.', '.#.#.#.', '.H.b.H.', '.###...'] }, t: "BIP! Mireu la ciutat: cada encàrrec és igual. Agafo la caixa, camino i la deixo a la casa. Si en faig una funció amb un <b>nom que s'entengui</b>, com «porta-la», el programa es llegirà com un pla: porta-la, gira, porta-la…|¡BIP! Mirad la ciudad: cada encargo es igual. Cojo la caja, camino y la dejo en la casa. Si hago una función con un <b>nombre que se entienda</b>, como «llévala», el programa se leerá como un plan: llévala, gira, llévala…" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Planificar|Planificar', t: 'Què es repeteix? Posa-hi nom!|¿Qué se repite? ¡Ponle nombre!', anim: 'u5plan',
          x: "Abans de posar blocs, mira el mapa i busca la feina que es repeteix. Si cada encàrrec és «agafar la caixa, caminar i deixar-la a la casa», aquest tros pot ser una funció que es digui <b>porta-la</b>.|Antes de poner bloques, mira el mapa y busca el trabajo que se repite. Si cada encargo es «coger la caja, caminar y dejarla en la casa», ese trozo puede ser una función que se llame <b>llévala</b>." },
        { k: 'Bons noms|Buenos nombres', t: 'Un nom que expliqui què fa|Un nombre que explique qué hace', demo: { w: { map: ['>b#Hb#H', '.......'] }, prog: 'A A', fns: { A: 'f p f f d' } },
          x: "Aquí la funció A és un encàrrec sencer: avança, agafa, avança dues vegades i deixa. Si li dius <b>porta-la</b> en lloc d'«A», tothom que llegeixi el programa entendrà què fa.|Aquí la función A es un encargo entero: avanza, coge, avanza dos veces y deja. Si la llamas <b>llévala</b> en lugar de «A», todo el que lea el programa entenderá qué hace.",
          bad: 'Noms com «coses» o «A», que no expliquen res.|Nombres como «cosas» o «A», que no explican nada.', good: 'Noms com «porta-la» o «puja», que diuen què fa la funció.|Nombres como «llévala» o «sube», que dicen qué hace la función.' },
        { k: 'Des d\'on és en Bit|Desde donde está Bit', t: 'La funció comença on és en Bit|La función empieza donde está Bit', anim: 'u5where',
          x: "La funció no porta en Bit a un lloc fix: fa els seus blocs <b>des d'on és i cap on mira</b>. Per això la mateixa «porta-la» serveix per a un carrer que va cap a la dreta, cap avall o cap amunt.|La función no lleva a Bit a un sitio fijo: hace sus bloques <b>desde donde está y hacia donde mira</b>. Por eso la misma «llévala» sirve para una calle que va hacia la derecha, hacia abajo o hacia arriba.",
          tip: "Abans de cridar-la, deixa en Bit a l'inici de l'encàrrec, mirant cap a la caixa.|Antes de llamarla, deja a Bit al principio del encargo, mirando hacia la caja." }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Quin és el millor nom per a una funció que agafa una caixa i la porta a la casa?|¿Cuál es el mejor nombre para una función que coge una caja y la lleva a la casa?', opts: ['porta-la|llévala', 'A|A', 'coses|cosas'], a: 0,
        ex: 'Un bon nom diu què fa la funció: així el programa s\'entén només de llegir-lo.|Un buen nombre dice qué hace la función: así el programa se entiende solo con leerlo.' },
      { k: 'seq', ph: 'mans', q: 'Així es planifica un projecte amb funcions. <b>Ordena els passos</b>.|Así se planifica un proyecto con funciones. <b>Ordena los pasos</b>.',
        items: ['Mira el mapa i busca la feina que es repeteix|Mira el mapa y busca el trabajo que se repite', 'Posa nom a la funció|Ponle nombre a la función', 'Escriu els blocs de la funció|Escribe los bloques de la función', 'Crida la funció al programa|Llama a la función en el programa', 'Prova-ho i, si falla, arregla la funció|Pruébalo y, si falla, arregla la función'],
        ex: 'Pla, nom, blocs, crides i proves: aquest és el camí del projecte d\'avui.|Plan, nombre, bloques, llamadas y pruebas: este es el camino del proyecto de hoy.' },
      { k: 'parsons', ph: 'prova', q: 'Primer encàrrec amb una funció ja feta: <b>porta-la</b>. <b>Ordena els blocs</b> del programa i executa\'l.|Primer encargo con una función ya hecha: <b>llévala</b>. <b>Ordena los bloques</b> del programa y ejecútalo.',
        w: { map: ['H....', '#....', 'b....', '#H#b<'] }, pool: TP('A f r A'), sol: TP('A f r A'), fns: { A: TQ('f p f f d') }, fnName: { A: 'porta-la|llévala' },
        hint: "En Bit mira a l'esquerra, cap a la primera caixa: comença amb porta-la. Després ha d'arribar a la cantonada i girar cap amunt.|Bit mira a la izquierda, hacia la primera caja: empieza con llévala. Después tiene que llegar a la esquina y girar hacia arriba." },
      { k: 'build', ph: 'repte', q: 'Ara escriu tu la funció <b>porta-la</b> i fes els dos encàrrecs. Màxim <b>8 blocs</b>.|Ahora escribe tú la función <b>llévala</b> y haz los dos encargos. Máximo <b>8 bloques</b>.',
        w: { map: ['>b#H.', '...b.', '...#.', '...H.'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'call'], fnEdit: ['A'], fnName: { A: 'porta-la|llévala' }, max: 8, sol: TQ('A r A'), solFns: { A: TQ('f p f f d') },
        hint: 'Porta-la: avança fins a la caixa, agafa-la, avança fins a la casa i deixa-la. Entre els dos encàrrecs, en Bit ha de girar.|Llévala: avanza hasta la caja, cógela, avanza hasta la casa y déjala. Entre los dos encargos, Bit tiene que girar.' },
      { k: 'move', ph: 'pausa', secs: 30, t: 'Fes de repartidor/a amb funcions! La funció <b>porta-la</b> és: ajup-te, agafa una caixa imaginària, fes 3 passos i deixa-la a terra. Ara: <b>porta-la, gira, porta-la, gira, porta-la!</b>|¡Haz de repartidor/a con funciones! La función <b>llévala</b> es: agáchate, coge una caja imaginaria, da 3 pasos y déjala en el suelo. Ahora: <b>¡llévala, gira, llévala, gira, llévala!</b>' },
      { k: 'build', ph: 'repte', q: 'La plaça del mercat té 4 costats, i a cada costat hi ha una caixa i una casa. El programa ja té el bucle: escriu la funció <b>costat de la plaça</b> (al final, en Bit ha de girar la cantonada).|La plaza del mercado tiene 4 lados, y en cada lado hay una caja y una casa. El programa ya tiene el bucle: escribe la función <b>lado de la plaza</b> (al final, Bit tiene que girar la esquina).',
        w: { map: ['>bH#', 'H..b', 'b..H', '#Hb#'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'rep', 'call'], prog: TQ('4{ A }'), fnEdit: ['A'], fnName: { A: 'costat de la plaça|lado de la plaza' }, sol: TQ('4{ A }'), solFns: { A: TQ('f p f d f r') },
        hint: 'Un costat: caixa, casa, cantonada i gir a la dreta. Prova primer la funció amb una sola volta del bucle.|Un lado: caja, casa, esquina y giro a la derecha. Prueba primero la función con una sola vuelta del bucle.' },
      { k: 'build', ph: 'repte', q: "Ui! La funció <b>porta-la</b> té un error: en Bit vol deixar la caixa abans d'arribar a la casa. Arregla la funció i fes els dos encàrrecs.|¡Uy! La función <b>llévala</b> tiene un error: Bit quiere dejar la caja antes de llegar a la casa. Arregla la función y haz los dos encargos.",
        w: { map: ['H#b<', 'b...', '#...', 'H...'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'call'], prog: TQ('A l A'), fns: { A: TQ('f p f d') }, fnEdit: ['A'], fnName: { A: 'porta-la|llévala' }, sol: TQ('A l A'), solFns: { A: TQ('f p f f d') },
        hint: 'Compta les caselles que hi ha entre la caixa i la casa. Quants Endavant calen?|Cuenta las casillas que hay entre la caja y la casa. ¿Cuántos Adelante hacen falta?' },
      { k: 'create', ph: 'crea', name: 'La ciutat dels robots|La ciudad de los robots', q: "<b>Projecte final de la unitat!</b> Reparteix les 3 caixes de la ciutat. Primer planifica: quina feina es repeteix? Escriu la funció <b>porta-la</b> (i la funció B, si et cal) i crida-les al programa.|<b>¡Proyecto final de la unidad!</b> Reparte las 3 cajas de la ciudad. Primero planifica: ¿qué trabajo se repite? Escribe la función <b>llévala</b> (y la función B, si te hace falta) y llámalas en el programa.",
        crit: ['Reparteix les 3 caixes a les 3 cases|Reparte las 3 cajas en las 3 casas', 'Fes servir almenys una funció|Usa al menos una función', 'El programa es llegeix com un pla: porta-la, gira, porta-la…|El programa se lee como un plan: llévala, gira, llévala…'],
        check: p => bitCountK(p, ['call']) ? null : 'Ja ho reparteixes tot! Ara fes-ho amb la funció <b>porta-la</b>: és el projecte de les ordres noves.|¡Ya lo repartes todo! Ahora hazlo con la función <b>llévala</b>: es el proyecto de las órdenes nuevas.',
        w: { map: ['>#.###.', '.b.H.b.', '.#.#.#.', '.H.b.H.', '.###...'] }, pal: ['fwd', 'left', 'right', 'pick', 'drop', 'rep', 'call'], fnEdit: ['A', 'B'], fnName: { A: 'porta-la|llévala' },
        sol: TQ('f r A B A f r f f r A'), solFns: { A: TQ('f p f f d'), B: TQ('f l f f l') } },
      { k: 'quiz', ph: 'tanca', q: 'Per què és bo posar a una funció un nom com <b>porta-la</b>?|¿Por qué es bueno poner a una función un nombre como <b>llévala</b>?', opts: ['Perquè quan llegeixes el programa entens què fa|Porque cuando lees el programa entiendes qué hace', 'Perquè en Bit va més de pressa|Porque Bit va más deprisa', 'Perquè els noms llargs ocupen menys blocs|Porque los nombres largos ocupan menos bloques'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Has fet servir la mateixa funció en carrers que anaven en direccions diferents. Per què funciona?|Has usado la misma función en calles que iban en direcciones distintas. ¿Por qué funciona?', opts: ["Perquè la funció fa els blocs des d'on és en Bit i cap on mira|Porque la función hace los bloques desde donde está Bit y hacia donde mira", 'Perquè la funció sempre porta en Bit al mateix lloc|Porque la función siempre lleva a Bit al mismo sitio', 'Perquè en Bit endevina on ha d\'anar|Porque Bit adivina adónde tiene que ir'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
